    public static Entry entry(String words){
        if(words.startsWith("do ")){var base=entry(words.substring(3));return base==null?null:new Entry("Выполнить EXEC-команду из режима настройки. "+base.purpose,base.arguments,base.limits);}
        var direct=ENTRIES.get(words);if(direct!=null)return direct;
        if(words.startsWith("no ")){var base=entry(words.substring(3));return base==null?null:new Entry("Отменить настройку или вернуть значение по умолчанию: "+base.purpose,base.arguments,base.limits);}
        return null;
    }
    public static String arguments(CommandGrammar.Spec spec,Console cli,Device d){
        var e=entry(spec.words());if(e==null)throw new IllegalArgumentException("Missing manual: "+spec.words());
        String args=e.arguments;
        if(spec.words().equals("network"))args=cli.mode==6?"192.168.10.0 255.255.255.0":cli.context.equals("ospf")?"192.168.10.0 0.0.0.255 area 0":cli.context.equals("eigrp")?"192.168.10.0 0.0.0.255":"192.168.10.0";
        if(spec.words().equals("spanning-tree vlan")&&cli.mode==3)args="10 cost 100";
        if(spec.maxArgs()==0)return "";
        if(spec.words().startsWith("no ")){var parts=args.split("\\s+");if(parts.length>spec.maxArgs())args=String.join(" ",Arrays.copyOf(parts,spec.maxArgs()));}
        return args;
    }
    public static String verification(String words){
        words=words.replaceFirst("^do ","").replaceFirst("^no ","");
        if(words.startsWith("show ")||Set.of("help","ping","traceroute","tracert","nslookup","arp","ipconfig","ipv6config","dir","netstat").contains(words))return "Сопоставь вывод с адресами, кабелями, VLAN и состоянием соседей. Ошибка или пустая таблица не означают успешную связь.";
        if(words.contains("nat"))return "show running-config; создай подходящий трафик, затем show ip nat translations и show ip nat statistics.";
        if(words.contains("access")||words.equals("permit")||words.equals("deny"))return "show access-lists и show running-config; проверь разрешённый и запрещённый поток отдельно.";
        if(words.contains("dhcp")||Set.of("default-router","dns-server","domain-name").contains(words))return "show ip dhcp pool / binding; на клиенте ipconfig /renew, затем ipconfig /all.";
        if(words.contains("spanning"))return "show spanning-tree vlan 10; проверь блокировку резервного пути в топологии с петлёй.";
        if(words.contains("mac address-table"))return "show mac address-table; после передачи проверь соответствие MAC, VLAN и порта.";
        if(words.contains("switchport")||words.equals("vlan")||words.equals("name"))return "show vlan brief; show interfaces trunk; проверь ping внутри VLAN и изоляцию другой VLAN.";
        if(words.contains("channel"))return "show etherchannel summary; проверь bundled/suspended и прохождение трафика.";
        if(words.startsWith("monitor"))return "show monitor session 1; создай трафик через порт-источник и проверь копии на анализаторе.";
        if(words.startsWith("router")||Set.of("network","router-id","passive-interface","variance","version","default-information originate","auto-summary").contains(words))return "show ip protocols и show ip route; для OSPF/EIGRP также проверь таблицу соседей и ping удалённой сети.";
        if(words.startsWith("ip route")||words.startsWith("ipv6 route"))return "show ip route / show ipv6 route; проверь удалённый адрес и обратный маршрут.";
        if(words.contains("secret")||words.contains("login")||words.equals("password")||words.equals("username")||words.contains("transport")||words.equals("ssh")||words.equals("telnet"))return "В новой сессии проверь правильные и неправильные учётные данные; для VTY также доступность TCP/22 или TCP/23.";
        return "Проверь текущий режим и show running-config; для интерфейса — show ip interface brief и обмен с соседом. Сохранение проверяй через show startup-config.";
    }
